const ref = (id) => String(id).replace(/-/g, '').slice(-10);
// nunca se le muestran códigos a la familia: cada «ref» se cambia por el nombre del movimiento
const limpia = (t, movs) => { let s = String(t || ''); (movs || []).forEach(m => { s = s.split(ref(m.id)).join('«' + m.concepto + '»'); }); return s.replace(/\s*\(?\b[0-9a-f]{10}\b\)?/g, '').replace(/\s{2,}/g, ' ').trim(); };
const sd = $getWorkflowStaticData('global');
const nuevos = $('Candidatos').first().json.nuevos || [];
const otros = $('Candidatos').first().json.otros || [];
const conocidos = nuevos.concat(otros);
let txt = String($input.first().json.output || '');
const m = txt.match(/\{[\s\S]*\}/);
let out = { preguntas: [] };
try { out = JSON.parse(m ? m[0] : txt); } catch (e) {}
const porId8 = id8 => conocidos.find(x => ref(x.id) === String(id8).replace(/-/g, '').slice(-10));
let n = 0;
for (const q of (out.preguntas || []).slice(0, 4)) {
  const movs = (q.ids || [q.id]).map(porId8).filter(Boolean);
  if (!movs.length || !q.pregunta) continue;
  // los montos que dice la pregunta deben ser de los movimientos que se muestran; si no, se descarta (nunca mostrar otro movimiento)
  const cifras = (String(q.pregunta).match(/\d{1,3}(?:\.\d{3})+/g) || []).map(s => Number(s.replace(/\./g, '')));
  const montos = movs.map(m => Math.round(m.monto));
  const suma = montos.reduce((a, b) => a + b, 0);
  if (cifras.some(c => !montos.includes(c) && c !== suma && !montos.some(a => montos.some(b => a + b === c)))) continue;
  sd.preguntas.push({ id: Date.now().toString(36) + (n++), estado: 'pendiente', pregunta: limpia(q.pregunta, movs).slice(0, 300),
    hilo: [{ r: 'a', t: limpia(q.pregunta, movs).slice(0, 300) }], opciones: (q.opciones || []).map(String).slice(0, 4), motivo: String(q.motivo || '').slice(0, 200), movs, creada: new Date().toISOString() });
}
// lo que la IA ya sabía por la memoria: se aplica sin preguntar
for (const a of (out.ya_se || [])) {
