const pend = sd.preguntas.filter(q => q.estado === 'pendiente' || (q.estado === 'saltada' && (q.hasta || '') <= hoy)).slice(0, 5).map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones, movs: q.movs, tipo: q.tipo || '', hilo: _h(q) }));
// todas las dudas sin resolver (también las que dejaron para después) y las últimas respondidas, para la pantalla «Dudas»
