const _lista = (_sd.preguntas || []);
const abiertas = _lista.filter(q => q.estado === 'pendiente' || q.estado === 'saltada').map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], saltada: q.estado === 'saltada', creada: q.creada || '', tipo: q.tipo || '', hilo: _h(q) }));
const hechas = _lista.filter(q => q.estado === 'respondida').slice(-8).reverse().map(q => ({ id: q.id, pregunta: q.pregunta, respuesta: q.respuesta || '', movs: q.movs || [], hilo: _h(q) }));
return [{ json: { abiertas, hechas, saber: _sd.memoria || [], ok: true, preguntas: pend, ajustes: sd.ajustes, memoria: sd.memoria.length } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
const p = sd.preguntas.find(q => q.id === v.id);
const linea = m => [ref(m.id), m.fecha, m.tipo, m.cat, Math.round(m.monto), m.concepto, m.notas].join(' | ');
const prompt = 'MEMORIA:
' + ((sd.memoria || []).map(f => '- ' + f).join('
') || '- (vacía)') +
  '

CONVERSACIÓN HASTA AHORA (Armoni = tú, Familia):
' + (p.hilo && p.hilo.length ? p.hilo : [{ r: 'a', t: p.pregunta }]).map(h => (h.r === 'a' ? 'Armoni: ' : 'Familia: ') + h.t).join('
') + '
MOVIMIENTOS (ref | fecha | tipo | categoría | monto | concepto | notas):
' + p.movs.map(linea).join('
') +
  '

RESPUESTA DE LA FAMILIA: ' + v.respuesta;
return [{ json: { prompt } }];

